def transform(grid):
    """Recolor trailing background after the final non-background cell in each row to 1."""
    out = [row[:] for row in grid]
    for row in out:
        occupied = [i for i, value in enumerate(row) if value != 8]
        if occupied:
            for i in range(occupied[-1] + 1, len(row)):
                if row[i] == 8:
                    row[i] = 1
    return out
